#include "bfs_bulk.h"

void bfs(
    node_t nodes[N_NODES],
    edge_t edges[N_EDGES],
    node_index_t starting_node,
    level_t level[N_NODES],
    edge_index_t level_counts[N_LEVELS])
{
    // Initialize starting node
    level[starting_node] = 0;

    // Initialize level counts
    for (int i = 0; i < N_LEVELS; i++) {
        level_counts[i] = 0;
    }
    level_counts[0] = 1;

    // Traverse levels
    for (int horizon = 0; horizon < N_LEVELS; horizon++) {
        // Iterate over nodes in the current level
        for (int n = 0; n < N_NODES; n++) {
            if (level[n] == horizon) {
                edge_index_t tmp_begin = nodes[n].edge_begin;
                edge_index_t tmp_end = nodes[n].edge_end;

                // Iterate over outgoing edges of the current node
                for (edge_index_t e = tmp_begin; e < tmp_end; e++) {
                    node_index_t tmp_dst = edges[e].dst;

                    // If the neighbor has not been visited, mark it
                    if (level[tmp_dst] == MAX_LEVEL) {
                        // Only assign a level if it fits in level_counts
                        if (horizon + 1 < N_LEVELS) {
                            level[tmp_dst] = (level_t)(horizon + 1);
                            level_counts[horizon + 1]++;
                        }
                    }
                }
            }
        }
    }
}
```

